package mandelbrot

import fpgalib._

import spinal.core._
import spinal.lib._
import spinal.lib.bus.avalon._

/** IOPLL generated by quartus/Makefile (ip-deploy altera_iopll): outclk_0 = core clock. */
class core_pll extends BlackBox {
  val refclk   = in Bool ()
  val rst      = in Bool ()
  val outclk_0 = out Bool ()
  val locked   = out Bool ()
}

/** DE25-Nano top level with the HPS (ROADMAP.md, phase 1). Port names are those of Terasic's
  * golden_top, so the pin assignments of the GHRD's golden_top.qsf apply unchanged.
  *
  * The HPS with its memory, MandelbrotAccel (registers on lwhps2fpga, results on f2sdram, the
  * interrupt on f2h_irq0 bit 0) and the fan controller.
  *
  * Clocks: CLOCK2_50 -> pll -> 100 MHz for the HPS bridges; CLOCK1_50 -> core_pll -> core clock;
  * CLOCK0_50 for the fan controller.
  * LED (on = low): 0 fan controller reachable on I2C, 1 accelerator busy, 7 heartbeat.
  */
class De25NanoHpsTop(cfg: AccelConfig = AccelConfig()) extends Component {
  val io = new Bundle {
    val CLOCK0_50, CLOCK1_50, CLOCK2_50 = in Bool ()
    val LED = out Bits (8 bits)

    val HDMI_I2C_SCL = inout(Analog(Bool()))
    val HDMI_I2C_SDA = inout(Analog(Bool()))

    val HPS     = HpsPins()
    val LPDDR4A = Lpddr4Pins()
  }
  noIoPrefix()
  io.HPS.setName("HPS")
  io.LPDDR4A.setName("LPDDR4A")

  // ---------------------------------------------------------------------------------- HPS
  val soc      = new qsys_top
  val initDone = !soc.ninit_done_ninit_done

  val bridgePll = new pll
  bridgePll.refclk := io.CLOCK2_50
  bridgePll.rst    := !initDone

  val bridgeClk = bridgePll.outclk_0
  soc.clk_100_clk   := bridgeClk
  soc.reset_reset_n := initDone
  soc.h2f_warm_reset_handshake_reset_ack := False // not used, as in the GHRD
  soc.connectPins(io.HPS, io.LPDDR4A)

  soc.f2h_irq1_in_irq := 0

  /** Reset asserted asynchronously, released synchronously to `clk`. */
  def syncReset(clk: Bool, rst: Bool): Bool = {
    val cd = ClockDomain(clk, config = ClockDomainConfig(resetKind = BOOT))
    ResetCtrl.asyncAssertSyncDeassert(rst, cd, inputPolarity = HIGH, outputPolarity = HIGH, bufferDepth = Some(3))
  }
  val bridgeRst = syncReset(bridgeClk, !initDone || !bridgePll.locked || soc.h2f_reset_reset)
  val bridgeCd  = ClockDomain(bridgeClk, bridgeRst)

  // ---------------------------------------------------------------------------------- fan
  val board = new BOARD_MANAGEMENT
  board.clk_50         := io.CLOCK0_50
  board.reset_n        := initDone
  board.Auto_Fan_Speed := True
  board.Set_Fan_Speed  := 5000 // only used without auto mode
  board.I2C_SCL <> io.HDMI_I2C_SCL
  board.I2C_SDA <> io.HDMI_I2C_SDA

  // ---------------------------------------------------------------------------------- accelerator
  val corePll = new core_pll
  corePll.refclk := io.CLOCK1_50
  corePll.rst    := !initDone
  val coreClk = corePll.outclk_0
  val coreRst = syncReset(coreClk, !initDone || !corePll.locked || soc.h2f_reset_reset)

  val platform = new AccelPlatform(cfg)
  platform.io.bridgeClk := bridgeClk
  platform.io.bridgeRst := bridgeRst
  platform.io.coreClk   := coreClk
  platform.io.coreRst   := coreRst

  platform.io.bus.address    := soc.reg_address
  platform.io.bus.read       := soc.reg_read
  platform.io.bus.write      := soc.reg_write
  platform.io.bus.writeData  := soc.reg_writedata
  platform.io.bus.byteEnable := soc.reg_byteenable
  soc.reg_readdata           := platform.io.bus.readData
  soc.reg_readdatavalid      := platform.io.bus.readDataValid
  soc.reg_waitrequest        := !platform.io.bus.waitRequestn
  platform.io.axi >> soc.f2sdram
  soc.f2h_irq_irq := platform.io.irq.asBits.resized

  platform.io.board.fpgaTemp  := board.FPGA_Temperature
  platform.io.board.boardTemp := board.Board_Temperature
  platform.io.board.fanRpm    := board.Fan_Speed
  platform.io.board.ready     := board.I2C_READY

  val bridge = new ClockingArea(bridgeCd) {
    val heartbeat = CounterFreeRun(BigInt(1) << 27).value.msb
  }

  io.LED := ~(bridge.heartbeat ## B(0, 5 bits) ## platform.io.busy ## board.I2C_READY)
}

/** Generates the DE25-Nano HPS top level (sp_De25NanoHpsTop.v) for quartus/.
  *
  * Usage: sbt "runMain mandelbrot.GenerateDe25NanoHps [key=value ...]"
  * Keys: targetDir width nCores fracWidth siLatency
  *  - width=21 (default): the narrow phase 1 cores; fracWidth and siLatency apply.
  *  - width=64, 96 or 128: the wide cores (I = 10, R = 16); nCores defaults to what the 188 DSP
  *    blocks allow (3 squares of WideParams.products 26x26 multipliers per core).
  */
object GenerateDe25NanoHps {
  private val keys = Set("targetDir", "width", "nCores", "fracWidth", "siLatency")
  val dspBlocks    = 188

  def main(args: Array[String]): Unit = {
    val kv = args.map { a =>
      a.split("=", 2) match {
        case Array(k, v) if keys(k) => k -> v
        case _ => sys.error(s"bad argument '$a', expected key=value with key in ${keys.mkString(", ")}")
      }
    }.toMap
    val d = AccelConfig()
    def int(k: String, v: Int) = kv.get(k).map(_.toInt).getOrElse(v)
    val width = int("width", d.w)
    val cfg =
      if (width == d.w)
        d.copy(nCores = int("nCores", d.nCores), fracWidth = int("fracWidth", d.fracWidth),
          siLatency = int("siLatency", d.siLatency))
      else {
        val p = WideParams(width)
        d.copy(intBits = p.i, fracWidth = p.f, wide = true,
          nCores = int("nCores", dspBlocks / (3 * p.products.size)))
      }
    println(s"[mandelbrot] generating De25NanoHpsTop with $cfg (W = ${cfg.w}, ${cfg.nCores} cores, " +
      s"pipeline ${cfg.latency})")
    MandelbrotSpinalConfig(kv.getOrElse("targetDir", "gen")).generateVerilog(new De25NanoHpsTop(cfg))
  }
}
